package world

import (
	"errors"
	"fmt"
	"os"
	"syscall"
)

// Record 是一次成功保存留下的、可供读取的记录。
type Record struct {
	// ID 是记录标识。
	ID RecordID
	// Parent 是父记录标识；槽首条记录为空。
	Parent RecordID
	// SlotFirst 表示这是其所在槽的首条记录。
	SlotFirst bool
	// State 是记录保存时的完整世界数据（深拷贝，修改不影响存档）。
	State State
}

func acquireSharedLock(dir string) (*fileLock, error) {
	path := dir + "/lock"
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
		f.Close()
		return nil, err
	}
	return &fileLock{f: f}, nil
}

// loadAndVerifyLocked 读取记录文件，校验其记录格式版本、内容校验和（校验和
// 已包含父记录关系）、父记录是否存在，以及世界数据是否自洽。
//
// 记录格式只支持 recordFormatVersion：格式编号缺失、为零、为负或为其他
// 正整数的记录按损坏处理，即使校验和匹配、世界状态合法、规则版本可被
// 调用方接受也不交付——目录能打开不代表每条记录都是当前功能理解的格式。
// 格式校验先于内容校验和：校验和载荷的布局本身由格式定义，未知格式的
// 记录无法解释其校验语义。格式问题与规则版本分别判断，格式错误一律报
// CorruptError，绝不报成 VersionRejectedError。
//
// 对完整世界状态的认可与 WorldFromState 重建世界保持一致：时间片为负的
// 记录属于损坏记录——内容校验和匹配只说明内容完整，规则版本被接受也不
// 能使负时间片合法；这样的记录不能被读回，也不能作为恢复或分支的来源。
func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
	env, err := loadRecord(recordPath(a.dir, id))
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, &NotFoundError{Record: id}
		}
		return nil, &CorruptError{Record: id, Reason: err.Error()}
	}
	if env.ID != id {
		return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
	}
	if env.Format != recordFormatVersion {
		return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("不支持的记录格式版本: %d", env.Format)}
	}
	if got := computeChecksum(env); got != env.Checksum {
		return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
	}
	// 父记录关系必须落到一个真实存在的记录上。
	if env.Parent != "" {
		if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
			if errors.Is(err, os.ErrNotExist) {
				return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
			}
			return nil, err
		}
	}
	// 时间片为负的记录与 WorldFromState 的拒绝保持一致：即使校验和匹配、
	// 其余状态合法，也按损坏处理，不自动把时间改成零。
	if env.State.Time < 0 {
		return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("记录中的时间片为负: %d", env.State.Time)}
	}
	if err := validateInitialData(InitialData{
		Seed:       env.State.Seed,
		Rules:      env.State.Rules,
		Characters: env.State.Characters,
	}); err != nil {
		return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
	}
	return env, nil
}

func versionAccepted(version string, accepted []string) bool {
	for _, v := range accepted {
		if v == version {
			return true
		}
	}
	return false
}

func envToRecord(env *envelope) Record {
	return Record{
		ID:        env.ID,
		Parent:    env.Parent,
		SlotFirst: env.SlotFirst,
		State:     cloneState(env.State),
	}
}

// Latest 读取槽当前最新记录。
//
// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
// 版本不在集合内时返回 *VersionRejectedError；记录损坏（格式版本不受支持、
// 校验和不符、父记录缺失、无法解析、时间片为负）时返回 *CorruptError。
// 格式与版本分别判断：格式不受支持的记录一律报损坏，不报版本拒绝。
// 读取不会改写存档。
func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
	if !validSlotName(slot) {
		return Record{}, &NotFoundError{Slot: slot}
	}
	lock, err := acquireSharedLock(a.dir)
	if err != nil {
		return Record{}, err
	}
	defer lock.release()

	id, err := a.readLatestLocked(slot)
	if err != nil {
		return Record{}, err
	}
	env, err := a.loadAndVerifyLocked(id)
	if err != nil {
		if ce, ok := err.(*CorruptError); ok {
			ce.Slot = slot
		}
		return Record{}, err
	}
	if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
		return Record{}, &VersionRejectedError{
			Slot:     slot,
			Record:   id,
			Version:  env.State.Rules.Version,
			Accepted: append([]string(nil), acceptedVersions...),
		}
	}
	return envToRecord(env), nil
}

// Record 按标识读取槽的一份历史记录（覆盖后的旧记录仍可读取）。
//
// 与 Latest 一样检查记录格式版本、内容校验和（含父记录关系）与规则版本，
// 且记录必须属于该槽的历史链。读取不会改写存档，也不会改变规则版本。
func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
	if !validSlotName(slot) {
		return Record{}, &NotFoundError{Slot: slot}
	}
	lock, err := acquireSharedLock(a.dir)
	if err != nil {
		return Record{}, err
	}
	defer lock.release()

	if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
		return Record{}, err
	}
	env, err := a.loadAndVerifyLocked(id)
	if err != nil {
		if ce, ok := err.(*CorruptError); ok {
			ce.Slot = slot
		}
		return Record{}, err
	}
	if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
		return Record{}, &VersionRejectedError{
			Slot:     slot,
			Record:   id,
			Version:  env.State.Rules.Version,
			Accepted: append([]string(nil), acceptedVersions...),
		}
	}
	return envToRecord(env), nil
}

// History 返回槽的历史记录元信息，按该槽保存生效的次序排列（最新在
// 前），到槽首条记录为止；分支槽只含它自己保存成功的记录，不会跨入
// 分支来源槽。次序来自槽指针内嵌的历史索引，与文件修改时间、世界时间
// 片或规则版本无关。
//
// 列出的每条元信息都对应历史中一份确实保存生效、且通过与 Record 一致
// 的完整性检查的记录：标识与文件一致、记录格式受支持、内容校验和正确
// （含父记录关系）、世界状态合法、直接父记录文件存在。损坏、缺失或无
// 法解析的单条记录一律略过，继续返回其余合格记录——最新记录或某条中间
// 记录出问题不会让整个列表失败；全部记录都被略过时返回空列表与成功
// 结果。完整性检查不包含规则版本取舍：History 没有可接受版本参数，
// 完好但规则版本较旧的记录仍正常列出。该方法只做只读遍历，不修补或
// 删除记录、不改变槽当前指向、不改写历史与世界规则。槽不存在返回
// *NotFoundError，槽指针无法解析返回 *CorruptError。
func (a *Archive) History(slot string) ([]RecordInfo, error) {
	if !validSlotName(slot) {
		return nil, &NotFoundError{Slot: slot}
	}
	lock, err := acquireSharedLock(a.dir)
	if err != nil {
		return nil, err
	}
	defer lock.release()

	history, err := a.slotHistoryLocked(slot)
	if err != nil {
		return nil, err
	}
	infos := make([]RecordInfo, 0, len(history))
	for _, id := range history {
		// 与 Record 相同的完整性检查（不做规则版本取舍）：任何一条
		// 记录损坏、缺失或无法解析都只略过它本身，不读其中的父标识或
		// 槽首标记去扩大或缩小遍历范围，也不让整个列表失败。
		env, verifyErr := a.loadAndVerifyLocked(id)
		if verifyErr != nil {
			continue
		}
		infos = append(infos, RecordInfo{
			ID:        env.ID,
			Parent:    env.Parent,
			SlotFirst: env.SlotFirst,
			Version:   env.State.Rules.Version,
		})
	}
	return infos, nil
}

// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
// 版本可接受的已保存记录。
//
// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。遍历
// 次序与世界时间片的大小无关；时间片为负的记录属于损坏记录，同样被越过。
// 格式版本不受支持的记录（即使校验和匹配、状态合法）同样被越过，连续
// 多份未知格式记录也不会遮住其后格式受支持的完好记录。
//
// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
// 不会被选中。
//
// 槽不存在返回 *NotFoundError；槽指针不可读返回 *CorruptError；槽中没有
// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
	if !validSlotName(slot) {
		return Record{}, &NotFoundError{Slot: slot}
	}
	lock, err := acquireSharedLock(a.dir)
	if err != nil {
		return Record{}, err
	}
	defer lock.release()

	history, err := a.slotHistoryLocked(slot)
	if err != nil {
		return Record{}, err
	}

	env, err := a.firstRecoverableLocked(history, acceptedVersions)
	if err != nil {
		var ue *UnrecoverableError
		if errors.As(err, &ue) {
			ue.Slot = slot
		}
		return Record{}, err
	}
	return envToRecord(env), nil
}

// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
//
// 文件缺失、截断、格式版本不受支持、校验和不符、记录标识不符、父关系异常、
// 时间片为负或世界状态不自洽的记录一律越过（不读其中的父标识或槽首标记）；
// 版本不被接受的记录也越过且不自动升级。次序完全由调用方给出（来自槽指针
// 历史索引或沿可信父链的重建），因此不会被引向别的槽。没有任何可用记录时
// 返回包装了 ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方
// 补全）。
func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
	var lastReason string
	for _, id := range history {
		env, verifyErr := a.loadAndVerifyLocked(id)
		if verifyErr != nil {
			lastReason = verifyErr.Error()
			continue
		}
		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
			lastReason = (&VersionRejectedError{
				Record:  id,
				Version: env.State.Rules.Version,
			}).Error()
			continue
		}
		return env, nil
	}

	if lastReason == "" {
		lastReason = "槽中没有任何可确认归属的历史记录"
	}
	return nil, &UnrecoverableError{Reason: lastReason}
}

package world_test

import (
	"errors"
	"fmt"
	"log"
	"os"

	"github.com/descikazuyq/world-rules/world"
)

// printContinueState 以固定格式打印一行世界状态，便于对照读档前后的变化。
func printContinueState(tag string, s world.State) {
	c := s.Characters[0]
	fmt.Printf("%s: time=%d %s@%s", tag, s.Time, c.ID, c.Location)
	for _, it := range c.Items {
		fmt.Printf(" %s=%d", it.Item, it.Count)
	}
	fmt.Println()
}

// Example_continueSavedGame 演示读档后在同一存档槽上继续：
// 首次保存（角色已有位置、物品和非零时间片）-> 重新打开存档 ->
// 显式给出可接受规则版本并读回当前记录 -> WorldFromState 承接完整状态 ->
// 内存中 Apply 一次合法移动与物品变化 -> 带读回记录标识 Replace 覆盖回原槽
// -> 分别读取新当前记录与被覆盖的旧记录；并演示版本拒绝与标识过期冲突。
func Example_continueSavedGame() {
	const slot = "adventure"
	acceptedV1 := []string{"v1"}

	// 示例规则：三个地点、两条无向道路、两种物品，hero 携带总量上限 10。
	rules := world.Rules{
		Version:   "v1",
		Locations: []string{"village", "forest", "mine"},
		Edges: []world.Edge{
			{From: "village", To: "forest"},
			{From: "forest", To: "mine"},
		},
		ItemKinds:   []string{"wood", "ore"},
		CarryLimits: map[string]int{"hero": 10},
	}

	dir, err := os.MkdirTemp("", "world-continue-*")
	if err != nil {
		log.Fatal(err)
	}
	defer os.RemoveAll(dir)

	// 1) 准备世界：NewWorld 的时间片固定从 0 开始。
	w0, err := world.NewWorld(world.InitialData{
		Seed:  20240801,
		Rules: rules,
		Characters: []world.Character{{
			ID:       "hero",
			Location: "village",
			Items: []world.CharacterItem{
				{Item: "wood", Count: 2},
				{Item: "ore", Count: 1},
			},
		}},
	})
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("新建", w0.Snapshot())

	// 推进到非零时间片：沿 village-forest 移动并改变物品数量，总量 4 <= 10。
	if _, err := w0.Apply(world.Commit{
		Moves:       []world.Move{{Character: "hero", To: "forest"}},
		ItemChanges: []world.ItemChange{{Character: "hero", Item: "wood", Delta: 1}},
		Time:        4,
	}); err != nil {
		log.Fatal(err)
	}

	// 2) 首次保存：创建命名槽，产生槽首记录；保存时角色已有位置、物品和
	// 非零时间片。
	arch0, err := world.Create(dir)
	if err != nil {
		log.Fatal(err)
	}
	if _, err := arch0.Save(slot, w0); err != nil {
		log.Fatal(err)
	}
	printContinueState("准备", w0.Snapshot())

	// 3) 另一次会话：重新打开这份存档，显式给出可接受的规则版本，读回槽
	// 当前记录。读取不改写存档。
	arch, err := world.Open(dir)
	if err != nil {
		log.Fatal(err)
	}
	rec, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}

	// 读回的记录保留种子、完整规则、角色物品内容与已保存的时间片。
	s := rec.State
	var roads []string
	for _, e := range s.Rules.Edges {
		roads = append(roads, e.From+"-"+e.To)
	}
	fmt.Printf("读档: seed=%d rules=%s time=%d\n", s.Seed, s.Rules.Version, s.Time)
	fmt.Printf("读档: places=%v roads=%v kinds=%v hero上限=%d\n",
		s.Rules.Locations, roads, s.Rules.ItemKinds, s.Rules.CarryLimits["hero"])
	printContinueState("读档", s)

	// 4) 承接完整状态重建可继续的世界：保留时间片 4。继续存档只能用
	// WorldFromState；NewWorld 建立的是时间从零开始的新世界。
	w, err := world.WorldFromState(rec.State)
	if err != nil {
		log.Fatal(err)
	}

	// Commit.Time 是目标绝对时间片，不是增加的步数：3 早于读回的 4，
	// 即使没有任何移动或物品变化也必须失败。
	if _, err := w.Apply(world.Commit{Time: 3}); err != nil {
		fmt.Printf("拒绝时间倒退: %v\n", err)
	}

	// 一次合法的继续：沿 forest-mine 道路移动，ore +2（1->3，总量 6 <= 10），
	// 目标绝对时间片为 7。
	if _, err := w.Apply(world.Commit{
		Moves:       []world.Move{{Character: "hero", To: "mine"}},
		ItemChanges: []world.ItemChange{{Character: "hero", Item: "ore", Delta: 2}},
		Time:        7,
	}); err != nil {
		log.Fatal(err)
	}
	printContinueState("继续", w.Snapshot())

	// Apply 成功只改变内存世界：槽内当前记录仍是覆盖前的内容。
	stored, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("存档未变", stored.State)

	// 5) 覆盖回原槽必须带上本次读回的记录标识：成功后得到独立的新标识，
	// 新记录以读回记录为父；first/rec 等旧记录不受影响。
	next, err := arch.Replace(slot, w, rec.ID)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("覆盖: 新标识独立=%t 以读回记录为父=%t\n",
		next.ID != rec.ID, next.Parent == rec.ID)

	cur, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("当前", cur.State)

	// 被覆盖的原记录仍可按其标识读取。
	old, err := arch.Record(slot, rec.ID, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("旧记录", old.State)

	// 失败条件一：记录规则版本不在可接受集合内 -> 版本拒绝，不能把这份
	// 记录当成新世界继续。
	if _, err := arch.Latest(slot, []string{"v9"}); err != nil {
		var vr *world.VersionRejectedError
		if !errors.As(err, &vr) {
			log.Fatal(err)
		}
		fmt.Printf("版本拒绝: %t 记录版本=%s\n", true, vr.Version)
	}

	// 失败条件二：读回的标识已经过期（槽刚被本次覆盖推进）-> 覆盖报冲突，
	// 已有当前记录保持原样。
	if _, err := arch.Replace(slot, w, rec.ID); err != nil {
		var ce *world.ConflictError
		if !errors.As(err, &ce) {
			log.Fatal(err)
		}
		fmt.Printf("冲突: 过期标识覆盖被拒绝=%t\n", true)
	}
	unchanged, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("当前仍在", unchanged.State)

	// 正确后续：重新读取当前记录后再决定。这里在内存世界上再做一次合法
	// 提交（mine->forest，ore -1，目标时间片 9），用重新读回的标识覆盖，
	// 新记录以重读标识为父。
	if _, err := w.Apply(world.Commit{
		Moves:       []world.Move{{Character: "hero", To: "forest"}},
		ItemChanges: []world.ItemChange{{Character: "hero", Item: "ore", Delta: -1}},
		Time:        9,
	}); err != nil {
		log.Fatal(err)
	}
	retried, err := arch.Replace(slot, w, unchanged.ID)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("重读后重试: 父记录为重读标识=%t\n", retried.Parent == unchanged.ID)
	final, err := arch.Latest(slot, acceptedV1)
	if err != nil {
		log.Fatal(err)
	}
	printContinueState("最终", final.State)

	// Output:
	// 新建: time=0 hero@village wood=2 ore=1
	// 准备: time=4 hero@forest wood=3 ore=1
	// 读档: seed=20240801 rules=v1 time=4
	// 读档: places=[village forest mine] roads=[village-forest forest-mine] kinds=[wood ore] hero上限=10
	// 读档: time=4 hero@forest wood=3 ore=1
	// 拒绝时间倒退: world: 时间不能倒退: 当前 4, 提交目标 3
	// 继续: time=7 hero@mine wood=3 ore=3
	// 存档未变: time=4 hero@forest wood=3 ore=1
	// 覆盖: 新标识独立=true 以读回记录为父=true
	// 当前: time=7 hero@mine wood=3 ore=3
	// 旧记录: time=4 hero@forest wood=3 ore=1
	// 版本拒绝: true 记录版本=v1
	// 冲突: 过期标识覆盖被拒绝=true
	// 当前仍在: time=7 hero@mine wood=3 ore=3
	// 重读后重试: 父记录为重读标识=true
	// 最终: time=9 hero@forest wood=3 ore=2
}

