1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"testing"
9	)
10	
11	// historyIDs 提取历史元信息中的记录标识。
12	func historyIDs(t *testing.T, infos []RecordInfo) []RecordID {
13		t.Helper()
14		ids := make([]RecordID, len(infos))
15		for i, info := range infos {
16			ids[i] = info.ID
17		}
18		return ids
19	}
20	
21	// assertHistoryIDs 断言历史元信息的标识序列与期望（保存生效次序）一致。
22	func assertHistoryIDs(t *testing.T, infos []RecordInfo, want []RecordID) {
23		t.Helper()
24		if got := historyIDs(t, infos); len(got) != len(want) {
25			t.Fatalf("历史应为 %v，得到 %v", want, got)
26		} else {
27			for i := range want {
28				if got[i] != want[i] {
29					t.Fatalf("历史次序错误: %v，期望 %v", got, want)
30				}
31			}
32		}
33	}
34	
35	// rewriteRulesVersion 改写记录中的规则版本并重算校验和，模拟一份完好但
36	// 规则版本较旧（或调用方未必接受）的记录。
37	func rewriteRulesVersion(t *testing.T, a *Archive, id RecordID, version string) {
38		t.Helper()
39		path := recordPath(a.dir, id)
40		env, err := loadRecord(path)
41		if err != nil {
42			t.Fatal(err)
43		}
44		env.State.Rules.Version = version
45		env.Checksum = computeChecksum(env)
46		data, err := json.MarshalIndent(env, "", "  ")
47		if err != nil {
48			t.Fatal(err)
49		}
50		if err := os.WriteFile(path, data, 0o600); err != nil {
51			t.Fatal(err)
52		}
53	}
54	
55	// TestHistoryTamperedLatestRuleVersion 本槽连续保存三次（首存 + 两次覆盖）
56	// 后，仅把最新记录的规则版本改成另一个值而不更新校验和：该记录用 Record
57	// 读取会因校验失败被拒绝，History 也应略过它，只留下前两次保存的记录；
58	// 其余元信息字段与记录内容一致，次序不变。
59	func TestHistoryTamperedLatestRuleVersion(t *testing.T) {
60		a, dir := newTestArchive(t)
61		ids := saveN(t, a, "s", 2) // r2 r1 r0
62	
63		// 只改最新记录里的规则版本，不重算校验和。
64		setRecordField(t, dir, ids[0], `"Version": "v1"`, `"Version": "v7"`)
65	
66		// 同一记录用 Record 读取按损坏拒绝，证明列表与读取采用同一完整性标准。
67		if _, err := a.Record("s", ids[0], []string{"v1"}); !errors.As(err, new(*CorruptError)) {
68			t.Fatalf("被改动的记录应被 Record 拒绝，得到 %T: %v", err, err)
69		}
70	
71		infos, err := a.History("s")
72		if err != nil {
73			t.Fatalf("最新记录损坏不应让整个列表失败: %v", err)
74		}
75		assertHistoryIDs(t, infos, []RecordID{ids[1], ids[2]})
76		if infos[0].Version != "v1" || infos[1].Version != "v1" {
77			t.Fatalf("完好记录的版本元信息应来自记录本身: %+v", infos)
78		}
79		if infos[0].Parent != ids[2] || infos[0].SlotFirst {
80			t.Fatalf("中间记录元信息错误: %+v", infos[0])
81		}
82		if infos[1].Parent != "" || !infos[1].SlotFirst {
83			t.Fatalf("槽首记录元信息错误: %+v", infos[1])
84		}
85	}
86	
87	// TestHistoryTamperedParentSkipped 中间记录的父标识被改动且不更新校验和时，
88	// 该记录被略过，最新记录（自身完好、直接父文件仍在）与更早记录继续保留。
89	func TestHistoryTamperedParentSkipped(t *testing.T) {
90		a, dir := newTestArchive(t)
91		ids := saveN(t, a, "s", 3) // r3 r2 r1 r0
92	
93		setRecordField(t, dir, ids[2], `"parent": "`+string(ids[3])+`"`,
94			`"parent": "r00000000000000000000000000000000"`)
95	
96		infos, err := a.History("s")
97		if err != nil {
98			t.Fatalf("History: %v", err)
99		}
100		assertHistoryIDs(t, infos, []RecordID{ids[0], ids[1], ids[3]})
101	}
102	
103	// TestHistorySkipsMissingTruncatedAndChecksumBad 最新记录校验和损坏、中间
104	// 记录被写成无法解析的内容（文件仍在）、另一条被截断：逐条略过，其余合格
105	// 记录按原保存次序返回。损坏文件仍占着位置，不影响其直接子记录的父文件
106	// 存在性检查；父文件被删除导致的连带略过另见专门用例。
107	func TestHistorySkipsMissingTruncatedAndChecksumBad(t *testing.T) {
108		a, dir := newTestArchive(t)
109		ids := saveN(t, a, "s", 4) // r4 r3 r2 r1 r0
110	
111		corruptChecksum(t, dir, ids[0])
112		truncateRecord(t, dir, ids[2])
113		if err := os.WriteFile(recordPath(dir, ids[3]), []byte("{not-json"), 0o600); err != nil {
114			t.Fatal(err)
115		}
116	
117		infos, err := a.History("s")
118		if err != nil {
119			t.Fatalf("History: %v", err)
120		}
121		// r3(ids[1]) 的直接父 r2 文件仍在（只是内容截断），r3 自身完好，保留；
122		// 槽首 r0(ids[4]) 保留。
123		assertHistoryIDs(t, infos, []RecordID{ids[1], ids[4]})
124	}
125	
126	// TestHistoryAllSkippedReturnsEmpty 槽存在且历史可确定、但所有记录都被略
127	// 过时，返回空列表和成功结果。
128	func TestHistoryAllSkippedReturnsEmpty(t *testing.T) {
129		a, dir := newTestArchive(t)
130		ids := saveN(t, a, "s", 2) // r2 r1 r0
131		for _, id := range ids {
132			corruptChecksum(t, dir, id)
133		}
134	
135		infos, err := a.History("s")
136		if err != nil {
137			t.Fatalf("全部损坏也应成功返回: %v", err)
138		}
139		if infos == nil {
140			t.Fatal("应返回非 nil 的空列表")
141		}
142		if len(infos) != 0 {
143			t.Fatalf("应返回空列表，得到 %+v", infos)
144		}
145	}
146	
147	// TestHistoryIntegrityFailuresAllSkipped 即便文件可解析、校验和也匹配，
148	// 格式不受支持或时间片为负的记录仍不完整，History 一律略过。
149	func TestHistoryIntegrityFailuresAllSkipped(t *testing.T) {
150		a, _ := newTestArchive(t)
151		ids := saveN(t, a, "s", 2) // r2 r1 r0
152	
153		// 最新记录：格式编号不受支持（已重算校验和）。
154		rewriteRecordFormat(t, a, ids[0], 2)
155		// 中间记录：时间片为负（已重算校验和）。
156		rewriteRecordTime(t, a, ids[1], -1)
157	
158		infos, err := a.History("s")
159		if err != nil {
160			t.Fatalf("History: %v", err)
161		}
162		assertHistoryIDs(t, infos, []RecordID{ids[2]})
163	}
164	
165	// TestHistoryListsIntactOldRuleVersion 完整性与规则版本是否适合调用方使用
166	// 是两回事：History 没有可接受版本参数，完好但规则版本较旧（或陌生）的
167	// 记录仍正常列出，元信息中的版本与记录一致。
168	func TestHistoryListsIntactOldRuleVersion(t *testing.T) {
169		a, _ := newTestArchive(t)
170		ids := saveN(t, a, "s", 1) // r1 r0
171	
172		// 最新记录完好、校验和正确，只是规则版本对某些调用方不可接受。
173		rewriteRulesVersion(t, a, ids[0], "v0-ancient")
174	
175		infos, err := a.History("s")
176		if err != nil {
177			t.Fatalf("History: %v", err)
178		}
179		if len(infos) != 2 {
180			t.Fatalf("完好的旧版本记录应正常列出: %+v", infos)
181		}
182		if infos[0].ID != ids[0] || infos[0].Version != "v0-ancient" {
183			t.Fatalf("旧版本记录元信息错误: %+v", infos[0])
184		}
185	}
186	
187	// TestHistoryMissingSlotAndCorruptPointer 槽不存在继续返回不存在错误；槽
188	// 指针无法解析继续返回损坏错误，不把它们当成空历史。
189	func TestHistoryMissingSlotAndCorruptPointer(t *testing.T) {
190		a, dir := newTestArchive(t)
191	
192		if _, err := a.History("nope"); !errors.As(err, new(*NotFoundError)) {
193			t.Fatalf("槽不存在应返回 *NotFoundError，得到 %T: %v", err, err)
194		}
195	
196		saveN(t, a, "s", 1)
197		if err := os.WriteFile(filepath.Join(dir, slotsName, "s.json"), []byte("{xx"), 0o600); err != nil {
198			t.Fatal(err)
199		}
200		if _, err := a.History("s"); !errors.As(err, new(*CorruptError)) {
201			t.Fatalf("槽指针无法解析应返回 *CorruptError，得到 %T: %v", err, err)
202		}
203	}
204	
205	// TestHistoryBranchListsOnlyOwnRecords 分支槽只列分支自身保存生效的记录，
206	// 不把来源槽的父记录补进列表，即使分支首记录以来源记录为直接父记录。
207	func TestHistoryBranchListsOnlyOwnRecords(t *testing.T) {
208		a, _ := newTestArchive(t)
209		ids := saveN(t, a, "s", 2) // r2 r1 r0
210	
211		b0, err := a.Branch("s", ids[1], "b")
212		if err != nil {
213			t.Fatal(err)
214		}
215		brec, err := a.Latest("b", []string{"v1"})
216		if err != nil {
217			t.Fatal(err)
218		}
219		w, err := WorldFromState(brec.State)
220		if err != nil {
221			t.Fatal(err)
222		}
223		if _, err := w.Apply(Commit{Time: 9}); err != nil {
224			t.Fatal(err)
225		}
226		b1, err := a.Replace("b", w, b0.ID)
227		if err != nil {
228			t.Fatal(err)
229		}
230	
231		bh, err := a.History("b")
232		if err != nil {
233			t.Fatalf("History: %v", err)
234		}
235		if len(bh) != 2 || bh[0].ID != b1.ID || bh[1].ID != b0.ID {
236			t.Fatalf("分支历史应只含分支自身记录: %+v", bh)
237		}
238		// 分支首记录以来源槽记录为父，但来源记录不得被补进列表。
239		if bh[1].Parent != ids[1] || !bh[1].SlotFirst {
240			t.Fatalf("分支首记录元信息错误: %+v", bh[1])
241		}
242		for _, info := range bh {
243			if info.ID == ids[0] || info.ID == ids[1] || info.ID == ids[2] {
244				t.Fatalf("来源槽记录不应进入分支历史: %+v", info)
245			}
246		}
247	
248		// 来源槽自己的历史不受分支影响。
249		sh, err := a.History("s")
250		if err != nil {
251			t.Fatalf("History: %v", err)
252		}
253		assertHistoryIDs(t, sh, ids)
254	}
255	
256	// TestHistoryParentCorruptButExistsDoesNotHideChild 父文件存在但内容损坏时，
257	// 不能仅因此隐藏自身通过检查的子记录；损坏的父记录本身被略过。
258	func TestHistoryParentCorruptButExistsDoesNotHideChild(t *testing.T) {
259		a, dir := newTestArchive(t)
260		ids := saveN(t, a, "s", 2) // r2 r1 r0
261	
262		corruptChecksum(t, dir, ids[1])
263	
264		infos, err := a.History("s")
265		if err != nil {
266			t.Fatalf("History: %v", err)
267		}
268		// ids[0] 的直接父文件 ids[1] 仍在，ids[0] 自身完好，照常列出。
269		assertHistoryIDs(t, infos, []RecordID{ids[0], ids[2]})
270	}
271	
272	// TestHistoryParentDeletedSkipsDirectChild 父文件被删除、使直接子记录不满足
273	// 既有父关系要求时，该子记录一并略过；其他可确认归属的完好记录保留。
274	func TestHistoryParentDeletedSkipsDirectChild(t *testing.T) {
275		a, dir := newTestArchive(t)
276		ids := saveN(t, a, "s", 2) // r2 r1 r0
277	
278		deleteRecord(t, dir, ids[1])
279	
280		infos, err := a.History("s")
281		if err != nil {
282			t.Fatalf("History: %v", err)
283		}
284		// ids[0] 的直接父 ids[1] 已删除 -> ids[0] 略过；槽首 ids[2] 保留。
285		assertHistoryIDs(t, infos, []RecordID{ids[2]})
286	}
287	
288	// TestHistoryLegacyPointerKeepsExistingScope 旧格式裸指针继续沿用已有的
289	// 历史归属范围：沿校验通过的父链重建，链在损坏记录处停止时，无法确认
290	// 归属的更老完好记录不进入列表。
291	func TestHistoryLegacyPointerKeepsExistingScope(t *testing.T) {
292		a, dir := newTestArchive(t)
293		ids := saveN(t, a, "s", 3) // r3 r2 r1 r0
294	
295		// 全部完好时：裸指针重建出完整链，次序与槽首标记均来自校验通过的记录。
296		writeLegacyPointer(t, a, "s", ids[0])
297		a2, err := Open(dir)
