1	package world
2	
3	import (
4		"fmt"
5		"sort"
6	)
7	
8	// BlockerKind 表示升级阻碍的类型。
9	type BlockerKind string
10	
11	const (
12		// BlockerLocation 表示角色所在地点在目标规则中已不存在。
13		BlockerLocation BlockerKind = "location"
14		// BlockerItem 表示角色携带的某种物品在目标规则中已不被允许。
15		BlockerItem BlockerKind = "item"
16		// BlockerLimit 表示角色携带总量超过目标规则给出的上限。
17		BlockerLimit BlockerKind = "limit"
18	)
19	
20	// Blocker 描述一条“目标规则无法原样承接当前角色状态”的具体阻碍。
21	type Blocker struct {
22		// Character 是受阻碍的角色标识。
23		Character string
24		// Kind 是阻碍类型。
25		Kind BlockerKind
26		// Location 是缺失的地点（Kind 为 BlockerLocation 时有值）。
27		Location string
28		// Item 是被移除的物品种类（Kind 为 BlockerItem 时有值）。
29		Item string
30		// Total 是角色当前携带总量（Kind 为 BlockerLimit 且 TotalOverflow
31		// 为 false 时有值，此时它就是真实总量）。
32		Total int
33		// TotalOverflow 表示真实携带总量超出 int 能表示的范围（来源规则未设
34		// 上限时可能出现）：此时 Total 不代表实际总量，调用方应改用
35		// TotalText 给出的完整十进制真实总量。
36		TotalOverflow bool
37		// TotalText 是真实携带总量的完整十进制表示（仅 TotalOverflow 为
38		// true 时有值）。
39		TotalText string
40		// Limit 是目标规则给出的新上限（Kind 为 BlockerLimit 时有值）。
41		Limit int
42	}
43	
44	// UpgradeCheck 描述对槽当前最新记录与目标规则的兼容性检查结果。
45	type UpgradeCheck struct {
46		// RecordID 是所检查的来源记录标识（槽当前最新记录）。
47		RecordID RecordID
48		// OldVersion 是来源记录的规则版本。
49		OldVersion string
50		// TargetVersion 是目标规则版本。
51		TargetVersion string
52		// Compatible 表示目标规则能否原样承接当前角色状态。
53		Compatible bool
54		// Blockers 是全部阻碍，按角色标识、物品标识排序；重复检查输出顺序一致。
55		Blockers []Blocker
56	}
57	
58	// UpgradeResult 是升级的返回结果。
59	type UpgradeResult struct {
60		// Check 是对当前来源记录与目标规则的兼容性检查结果。
61		Check UpgradeCheck
62		// Record 是成功时新记录的元信息；被阻碍时为零值。
63		Record RecordInfo
64	}
65	
66	// checkCompatibility 计算用 target 规则原样承接 st 中全部角色状态的阻碍。
67	//
68	// 兼容只判断能否原样承接当前角色状态：每个角色所在地点仍存在，已列出的
69	// 物品种类仍被允许（数量为零也算），各角色携带总量不超过目标上限（按真实
70	// 总量精确求和，不因回绕放过超限；真实总量超出 int 范围时阻碍置
71	// TotalOverflow 并以 TotalText 给出完整十进制总量）；目标中没有该角色上限
72	// 时表示不设上限。允许删去无人所在的地点、不再出现的物品种类或旧连通关系，
73	// 也允许增加内容。升级后移动和物品变化按目标规则处理。
74	func checkCompatibility(st State, target Rules) []Blocker {
75		locSet := make(map[string]struct{}, len(target.Locations))
76		for _, l := range target.Locations {
77			locSet[l] = struct{}{}
78		}
79		kindSet := make(map[string]struct{}, len(target.ItemKinds))
80		for _, k := range target.ItemKinds {
81			kindSet[k] = struct{}{}
82		}
83		var blockers []Blocker
84		for _, ch := range st.Characters {
85			if _, ok := locSet[ch.Location]; !ok {
86				blockers = append(blockers, Blocker{
87					Character: ch.ID,
88					Kind:      BlockerLocation,
89					Location:  ch.Location,
90				})
91			}
92			for _, it := range ch.Items {
93				if _, ok := kindSet[it.Item]; !ok {
94					blockers = append(blockers, Blocker{
95						Character: ch.ID,
96						Kind:      BlockerItem,
97						Item:      it.Item,
98					})
99				}
100			}
101			// 携带上限按真实总量判断，与建立/重建世界、提交物品变化共用同一
102			// 口径（精确求和不因回绕放过超限，目标中没有该角色上限时表示不设
103			// 上限）。真实总量能用 int 表示时沿用 Total 字段；超出 int 范围时
104			// 置 TotalOverflow 并给出完整十进制 TotalText，绝不返回回绕值。
105			if limit, ok := target.CarryLimits[ch.ID]; ok {
106				total := carryTotal(ch.Items)
107				if totalExceedsLimit(total, limit) {
108					b := Blocker{
109						Character: ch.ID,
110						Kind:      BlockerLimit,
111						Limit:     limit,
112					}
113					if total.Cmp(maxIntBig) <= 0 {
114						b.Total = int(total.Int64())
115					} else {
116						b.TotalOverflow = true
117						b.TotalText = total.String()
118					}
119					blockers = append(blockers, b)
120				}
121			}
122		}
123		// 同类问题按角色标识、物品标识排序；location/limit 阻碍没有物品标识，
124		// 以空物品标识参与排序，保证重复检查输出顺序一致。跨类别按
125		// location、item、limit 的自然顺序分组，便于阅读。
126		kindRank := func(k BlockerKind) int {
127			switch k {
128			case BlockerLocation:
129				return 0
130			case BlockerItem:
131				return 1
132			case BlockerLimit:
133				return 2
134			}
135			return 3
136		}
137		sort.SliceStable(blockers, func(i, j int) bool {
138			if blockers[i].Character != blockers[j].Character {
139				return blockers[i].Character < blockers[j].Character
140			}
141			if blockers[i].Kind != blockers[j].Kind {
142				return kindRank(blockers[i].Kind) < kindRank(blockers[j].Kind)
143			}
144			return blockers[i].Item < blockers[j].Item
145		})
146		return blockers
147	}
148	
149	// checkUpgradeLocked 在调用方已持锁（共享或排他均可）的前提下读取并校验
150	// 槽当前最新记录，计算目标规则的兼容性。来源读取、完整性检查、可接受
151	// 版本与版本相异判断共用 sourceForTransformLocked，本函数只负责升级自己
152	// 的兼容性计算。返回检查结果与来源记录信封。
153	func (a *Archive) checkUpgradeLocked(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, *envelope, error) {
154		latest, env, err := a.sourceForTransformLocked(slot, acceptedVersions, target.Version)
155		if err != nil {
156			return UpgradeCheck{}, nil, err
157		}
158		check := UpgradeCheck{
159			RecordID:      latest,
160			OldVersion:    env.State.Rules.Version,
161			TargetVersion: target.Version,
162		}
163		blockers := checkCompatibility(env.State, target)
164		check.Compatible = len(blockers) == 0
165		check.Blockers = blockers
166		return check, env, nil
167	}
168	
169	// CheckUpgrade 检查槽当前最新记录能否在目标规则下继续使用。
170	//
171	// 检查只读取来源记录并计算兼容性，不改变世界、历史或槽当前记录，也不会
172	// 替换记录中的规则。target 必须先满足规则自身的合法性要求，且版本与来源
173	// 记录不同（版本只按相等判断，不按数字大小限制升级）。
174	//
175	// 目标规则非法返回 *RuleError；版本相同返回 *RuleError；来源损坏返回
176	// *CorruptError；来源版本不在 acceptedVersions 内返回 *VersionRejectedError；
177	// 槽不存在沿用现有不存在错误。
178	func (a *Archive) CheckUpgrade(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, error) {
179		if !validSlotName(slot) {
180			return UpgradeCheck{}, &NotFoundError{Slot: slot}
181		}
182		if err := validateRules(target); err != nil {
183			return UpgradeCheck{}, err
184		}
185		lock, err := acquireSharedLock(a.dir)
186		if err != nil {
187			return UpgradeCheck{}, err
188		}
189		defer lock.release()
190		check, _, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
191		if err != nil {
192			return UpgradeCheck{}, err
193		}
194		return check, nil
195	}
196	
197	// Upgrade 在检查通过后用目标规则生成一条新记录。
198	//
199	// 传入与 CheckUpgrade 相同的条件，并带调用方预期的最新记录标识 expected。
200	// 提交时在排他锁下重新判断当前来源：仍有阻碍则返回相同的阻碍信息并拒绝
201	// 写入；expected 为空或已不是该槽最新记录时返回现有冲突错误。
202	//
203	// 被拒绝的升级不增加历史记录，也不改变槽当前记录。成功后槽增加一条完整
204	// 的新记录，以被升级记录为父，保存目标规则；种子、时间片、角色位置及
205	// 物品数量和排列保持原样。并发升级或升级与普通覆盖竞争时，只有 expected
206	// 与最新记录一致的一个成功，其余收到冲突。
207	func (a *Archive) Upgrade(slot string, acceptedVersions []string, target Rules, expected RecordID) (UpgradeResult, error) {
208		if !validSlotName(slot) {
209			return UpgradeResult{}, &NotFoundError{Slot: slot}
210		}
211		if err := validateRules(target); err != nil {
212			return UpgradeResult{}, err
213		}
214		if expected == "" {
215			return UpgradeResult{}, &ConflictError{Slot: slot, Reason: "升级必须提供所依据的记录标识"}
216		}
217		lock, err := acquireLock(a.dir)
218		if err != nil {
219			return UpgradeResult{}, err
220		}
221		defer lock.release()
222	
223		oldPointer, err := a.readSlotPointerLocked(slot)
224		if err != nil {
225			return UpgradeResult{}, err
226		}
227		latest := oldPointer.Latest
228		if latest != expected {
229			return UpgradeResult{}, &ConflictError{
230				Slot:   slot,
231				Reason: "所依据的记录已不是该槽最新记录",
232			}
233		}
234	
235		check, env, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
236		if err != nil {
237			return UpgradeResult{}, err
238		}
239		if !check.Compatible {
240			return UpgradeResult{Check: check}, &RuleError{
241				Reason: fmt.Sprintf("升级被阻碍: 目标规则无法承接当前角色状态（%d 处阻碍）", len(check.Blockers)),
242			}
243		}
244	
245		// 升级保存目标规则，种子、时间片、角色位置及物品数量和排列原样保留；
246		// 以被升级记录为父，沿用共同的新记录组装、落盘与槽指针提交路径。
247		newState := State{
248			Seed:       env.State.Seed,
249			Rules:      cloneRules(target),
250			Time:       env.State.Time,
251			Characters: cloneCharacters(env.State.Characters),
252		}
253		info, err := a.appendSlotRecordLocked(slotSave{
254			slot:          slot,
255			oldPointer:    oldPointer,
256			parent:        expected,
257			historyAnchor: latest,
258			state:         newState,
259		})
260		if err != nil {
261			return UpgradeResult{}, err
262		}
263		return UpgradeResult{Check: check, Record: info}, nil
264	}
