package world

import (
	"fmt"
	"sort"
)

// BlockerKind 表示升级阻碍的类型。
type BlockerKind string

const (
	// BlockerLocation 表示角色所在地点在目标规则中已不存在。
	BlockerLocation BlockerKind = "location"
	// BlockerItem 表示角色携带的某种物品在目标规则中已不被允许。
	BlockerItem BlockerKind = "item"
	// BlockerLimit 表示角色携带总量超过目标规则给出的上限。
	BlockerLimit BlockerKind = "limit"
)

// Blocker 描述一条“目标规则无法原样承接当前角色状态”的具体阻碍。
type Blocker struct {
	// Character 是受阻碍的角色标识。
	Character string
	// Kind 是阻碍类型。
	Kind BlockerKind
	// Location 是缺失的地点（Kind 为 BlockerLocation 时有值）。
	Location string
	// Item 是被移除的物品种类（Kind 为 BlockerItem 时有值）。
	Item string
	// Total 是角色当前携带总量（Kind 为 BlockerLimit 且 TotalOverflow
	// 为 false 时有值，此时它就是真实总量）。
	Total int
	// TotalOverflow 表示真实携带总量超出 int 能表示的范围（来源规则未设
	// 上限时可能出现）：此时 Total 不代表实际总量，调用方应改用
	// TotalText 给出的完整十进制真实总量。
	TotalOverflow bool
	// TotalText 是真实携带总量的完整十进制表示（仅 TotalOverflow 为
	// true 时有值）。
	TotalText string
	// Limit 是目标规则给出的新上限（Kind 为 BlockerLimit 时有值）。
	Limit int
}

// UpgradeCheck 描述对槽当前最新记录与目标规则的兼容性检查结果。
type UpgradeCheck struct {
	// RecordID 是所检查的来源记录标识（槽当前最新记录）。
	RecordID RecordID
	// OldVersion 是来源记录的规则版本。
	OldVersion string
	// TargetVersion 是目标规则版本。
	TargetVersion string
	// Compatible 表示目标规则能否原样承接当前角色状态。
	Compatible bool
	// Blockers 是全部阻碍，按角色标识、物品标识排序；重复检查输出顺序一致。
	Blockers []Blocker
}

// UpgradeResult 是升级的返回结果。
type UpgradeResult struct {
	// Check 是对当前来源记录与目标规则的兼容性检查结果。
	Check UpgradeCheck
	// Record 是成功时新记录的元信息；被阻碍时为零值。
	Record RecordInfo
}

// checkCompatibility 计算用 target 规则原样承接 st 中全部角色状态的阻碍。
//
// 兼容只判断能否原样承接当前角色状态：每个角色所在地点仍存在，已列出的
// 物品种类仍被允许（数量为零也算），各角色携带总量不超过目标上限（按真实
// 总量精确求和，不因回绕放过超限；真实总量超出 int 范围时阻碍置
// TotalOverflow 并以 TotalText 给出完整十进制总量）；目标中没有该角色上限
// 时表示不设上限。允许删去无人所在的地点、不再出现的物品种类或旧连通关系，
// 也允许增加内容。升级后移动和物品变化按目标规则处理。
func checkCompatibility(st State, target Rules) []Blocker {
	locSet := make(map[string]struct{}, len(target.Locations))
	for _, l := range target.Locations {
		locSet[l] = struct{}{}
	}
	kindSet := make(map[string]struct{}, len(target.ItemKinds))
	for _, k := range target.ItemKinds {
		kindSet[k] = struct{}{}
	}
	var blockers []Blocker
	for _, ch := range st.Characters {
		if _, ok := locSet[ch.Location]; !ok {
			blockers = append(blockers, Blocker{
				Character: ch.ID,
				Kind:      BlockerLocation,
				Location:  ch.Location,
			})
		}
		for _, it := range ch.Items {
			if _, ok := kindSet[it.Item]; !ok {
				blockers = append(blockers, Blocker{
					Character: ch.ID,
					Kind:      BlockerItem,
					Item:      it.Item,
				})
			}
		}
		// 携带上限按真实总量判断，与建立/重建世界、提交物品变化共用同一
		// 口径（精确求和不因回绕放过超限，目标中没有该角色上限时表示不设
		// 上限）。真实总量能用 int 表示时沿用 Total 字段；超出 int 范围时
		// 置 TotalOverflow 并给出完整十进制 TotalText，绝不返回回绕值。
		if limit, ok := target.CarryLimits[ch.ID]; ok {
			total := carryTotal(ch.Items)
			if totalExceedsLimit(total, limit) {
				b := Blocker{
					Character: ch.ID,
					Kind:      BlockerLimit,
					Limit:     limit,
				}
				if total.Cmp(maxIntBig) <= 0 {
					b.Total = int(total.Int64())
				} else {
					b.TotalOverflow = true
					b.TotalText = total.String()
				}
				blockers = append(blockers, b)
			}
		}
	}
	// 同类问题按角色标识、物品标识排序；location/limit 阻碍没有物品标识，
	// 以空物品标识参与排序，保证重复检查输出顺序一致。跨类别按
	// location、item、limit 的自然顺序分组，便于阅读。
	kindRank := func(k BlockerKind) int {
		switch k {
		case BlockerLocation:
			return 0
		case BlockerItem:
			return 1
		case BlockerLimit:
			return 2
		}
		return 3
	}
	sort.SliceStable(blockers, func(i, j int) bool {
		if blockers[i].Character != blockers[j].Character {
			return blockers[i].Character < blockers[j].Character
		}
		if blockers[i].Kind != blockers[j].Kind {
			return kindRank(blockers[i].Kind) < kindRank(blockers[j].Kind)
		}
		return blockers[i].Item < blockers[j].Item
	})
	return blockers
}

// checkUpgradeLocked 在调用方已持锁（共享或排他均可）的前提下读取并校验
// 槽当前最新记录，计算目标规则的兼容性。来源读取、完整性检查、可接受
// 版本与版本相异判断共用 sourceForTransformLocked，本函数只负责升级自己
// 的兼容性计算。返回检查结果与来源记录信封。
func (a *Archive) checkUpgradeLocked(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, *envelope, error) {
	latest, env, err := a.sourceForTransformLocked(slot, acceptedVersions, target.Version)
	if err != nil {
		return UpgradeCheck{}, nil, err
	}
	check := UpgradeCheck{
		RecordID:      latest,
		OldVersion:    env.State.Rules.Version,
		TargetVersion: target.Version,
	}
	blockers := checkCompatibility(env.State, target)
	check.Compatible = len(blockers) == 0
	check.Blockers = blockers
	return check, env, nil
}

// CheckUpgrade 检查槽当前最新记录能否在目标规则下继续使用。
//
// 检查只读取来源记录并计算兼容性，不改变世界、历史或槽当前记录，也不会
// 替换记录中的规则。target 必须先满足规则自身的合法性要求，且版本与来源
// 记录不同（版本只按相等判断，不按数字大小限制升级）。
//
// 目标规则非法返回 *RuleError；版本相同返回 *RuleError；来源损坏返回
// *CorruptError；来源版本不在 acceptedVersions 内返回 *VersionRejectedError；
// 槽不存在沿用现有不存在错误。
func (a *Archive) CheckUpgrade(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, error) {
	if !validSlotName(slot) {
		return UpgradeCheck{}, &NotFoundError{Slot: slot}
	}
	if err := validateRules(target); err != nil {
		return UpgradeCheck{}, err
	}
	lock, err := acquireSharedLock(a.dir)
	if err != nil {
		return UpgradeCheck{}, err
	}
	defer lock.release()
	check, _, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
	if err != nil {
		return UpgradeCheck{}, err
	}
	return check, nil
}

// Upgrade 在检查通过后用目标规则生成一条新记录。
//
// 传入与 CheckUpgrade 相同的条件，并带调用方预期的最新记录标识 expected。
// 提交时在排他锁下重新判断当前来源：仍有阻碍则返回相同的阻碍信息并拒绝
// 写入；expected 为空或已不是该槽最新记录时返回现有冲突错误。
//
// 被拒绝的升级不增加历史记录，也不改变槽当前记录。成功后槽增加一条完整
// 的新记录，以被升级记录为父，保存目标规则；种子、时间片、角色位置及
// 物品数量和排列保持原样。并发升级或升级与普通覆盖竞争时，只有 expected
// 与最新记录一致的一个成功，其余收到冲突。
func (a *Archive) Upgrade(slot string, acceptedVersions []string, target Rules, expected RecordID) (UpgradeResult, error) {
	if !validSlotName(slot) {
		return UpgradeResult{}, &NotFoundError{Slot: slot}
	}
	if err := validateRules(target); err != nil {
		return UpgradeResult{}, err
	}
	if expected == "" {
		return UpgradeResult{}, &ConflictError{Slot: slot, Reason: "升级必须提供所依据的记录标识"}
	}
	lock, err := acquireLock(a.dir)
	if err != nil {
		return UpgradeResult{}, err
	}
	defer lock.release()

	oldPointer, err := a.readSlotPointerLocked(slot)
	if err != nil {
		return UpgradeResult{}, err
	}
	latest := oldPointer.Latest
	if latest != expected {
		return UpgradeResult{}, &ConflictError{
			Slot:   slot,
			Reason: "所依据的记录已不是该槽最新记录",
		}
	}

	check, env, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
	if err != nil {
		return UpgradeResult{}, err
	}
	if !check.Compatible {
		return UpgradeResult{Check: check}, &RuleError{
			Reason: fmt.Sprintf("升级被阻碍: 目标规则无法承接当前角色状态（%d 处阻碍）", len(check.Blockers)),
		}
	}

	// 升级保存目标规则，种子、时间片、角色位置及物品数量和排列原样保留；
	// 以被升级记录为父，沿用共同的新记录组装、落盘与槽指针提交路径。
	newState := State{
		Seed:       env.State.Seed,
		Rules:      cloneRules(target),
		Time:       env.State.Time,
		Characters: cloneCharacters(env.State.Characters),
	}
	info, err := a.appendSlotRecordLocked(slotSave{
		slot:          slot,
		oldPointer:    oldPointer,
		parent:        expected,
		historyAnchor: latest,
		state:         newState,
	})
	if err != nil {
		return UpgradeResult{}, err
	}
	return UpgradeResult{Check: check, Record: info}, nil
}

package world

// slotSave 描述“在一个已存在的槽中追加一条新记录”所需的、与具体操作
// 无关的要素。普通覆盖、规则升级、显式迁移与确认恢复在通过各自的前提
// 检查后，统一用它来完成新记录的组装、落盘与槽指针提交；各操作特有的
// 状态处理（快照、换规则原样保留、转换结果、整份复制）与提交条件仍由
// 调用方在持锁前提下先行确定。
type slotSave struct {
	// slot 是新记录所属的槽名。
	slot string
	// oldPointer 是提交前读到的槽指针；历史索引为空（旧格式裸指针）时
	// 会沿可信父链在内存中重建，承接旧历史。
	oldPointer slotPointer
	// parent 是新记录的父标识：覆盖/升级/迁移为提交所依据的当前（来源）
	// 记录；确认恢复为选中的来源记录（即使它就是当前记录）。
	parent RecordID
	// historyAnchor 是历史承接点：旧指针无内嵌历史索引时，从它开始沿
	// 可信父链重建此前的保存次序。覆盖/升级/迁移即被提交的当前记录；
	// 确认恢复允许当前记录已损坏或被删除，故以槽指针的当前指向为准。
	historyAnchor RecordID
	// state 是新记录保存的完整世界状态，内容含义由各操作决定。
	state State
}

// appendSlotRecordLocked 集中四个追加型保存操作的共同职责，调用方必须已
// 持有排他锁并完成各自的前提校验（槽存在、乐观锁一致、阻碍检查、来源
// 归属与版本校验等）。
//
// 它依次：生成独立的新记录标识；组装信封并计算内容校验和（含父关系）；
// 以临时文件写全 + 原子改名落盘；记录完整生效后才把新记录按保存次序前置
// 进历史并原子更新槽指针。旧历史沿用原保存次序，只做承接不重排——既不按
// 时间片或文件时间排序，也不沿来源的父链截断。崩溃在指针更新前发生时，
// 槽保持原指向与原历史，新记录因未进入历史索引而不会成为恢复候选。
//
// 返回的 RecordInfo 的标识、父记录与规则版本与实际落盘的记录一致；这些
// 追加产生的记录都不是槽首记录。
func (a *Archive) appendSlotRecordLocked(sv slotSave) (RecordInfo, error) {
	id, err := newRecordID()
	if err != nil {
		return RecordInfo{}, err
	}
	env := &envelope{
		Format: recordFormatVersion,
		ID:     id,
		Parent: sv.parent,
		// 追加记录即使复制自槽首来源，也只是本槽保存次序最前的一条
		// 普通记录，不沿用来源的槽首标记。
		SlotFirst: false,
		State:     sv.state,
	}
	env.Checksum = computeChecksum(env)
	if err := writeRecord(a.dir, env); err != nil {
		return RecordInfo{}, err
	}
	if err := a.commitSlotPointerLocked(sv.slot, sv.oldPointer, sv.historyAnchor, id); err != nil {
		return RecordInfo{}, err
	}
	return RecordInfo{
		ID:      id,
		Parent:  sv.parent,
		Version: sv.state.Rules.Version,
	}, nil
}

