// 完好但规则版本较旧的记录仍正常列出。该方法只做只读遍历，不修补或
// 删除记录、不改变槽当前指向、不改写历史与世界规则。槽不存在返回
// *NotFoundError，槽指针无法解析返回 *CorruptError。
func (a *Archive) History(slot string) ([]RecordInfo, error) {
